SELECT genre_id
  FROM genre
 WHERE external_genre_id = #{externalGenreId}

SELECT A.*, B.* FROM ( SELECT tt1.rnum no, tt1.genre_id, tt1.external_genre_id, tt1.name FROM ( SELECT ROWNUM rnum, t1.* FROM ( SELECT * FROM genre
ORDER BY genre_id ASC ) t1 WHERE ROWNUM <= (#{pageSize} * (#{pageNo} - 1) + #{pageSize}) ) tt1 WHERE rnum >= (#{pageSize} * (#{pageNo} - 1) + 1) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM genre
) B

mapper.update:
UPDATE genre
   SET external_genre_id = #{externalGenreId, jdbcType=VARCHAR},
       name              = #{name, jdbcType=NVARCHAR}
 WHERE genre_id = #{genreId}
